/**
 * Where uploaded files live. Local NAS folder by default; an S3-compatible bucket is optional.
 * Keys are generated by the server (never the user's file name).
 */
import crypto from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';
import { Readable } from 'node:stream';
import type { Config } from '../config';

export interface BlobStore {
  readonly driver: 'local' | 's3';
  put(key: string, data: Buffer): Promise<void>;
  get(key: string): Promise<Readable | null>;
  delete(key: string): Promise<void>;
  /** Free and total bytes on the disk holding the files, where known. */
  space(): Promise<{ free: number; total: number } | null>;
  check(): Promise<string | null>;
}

const SAFE_KEY = /^[a-z0-9_-]+(\/[a-z0-9._-]+)+$/i;

export class LocalBlobs implements BlobStore {
  readonly driver = 'local';
  constructor(private readonly root: string) {}
  private file(key: string) {
    if (!SAFE_KEY.test(key) || key.includes('..')) throw new Error('bad storage key');
    return path.join(this.root, ...key.split('/'));
  }
  async put(key: string, data: Buffer) {
    const f = this.file(key);
    await fs.promises.mkdir(path.dirname(f), { recursive: true, mode: 0o750 });
    const tmp = `${f}.part-${crypto.randomBytes(4).toString('hex')}`;
    await fs.promises.writeFile(tmp, data, { mode: 0o640 });
    await fs.promises.rename(tmp, f);
  }
  async get(key: string) {
    const f = this.file(key);
    try {
      await fs.promises.access(f);
    } catch {
      return null;
    }
    return fs.createReadStream(f);
  }
  async delete(key: string) {
    await fs.promises.rm(this.file(key), { force: true });
  }
  async space() {
    try {
      const s = await fs.promises.statfs(this.root);
      return { free: s.bavail * s.bsize, total: s.blocks * s.bsize };
    } catch {
      return null;
    }
  }
  async check() {
    try {
      await fs.promises.mkdir(this.root, { recursive: true });
      const probe = path.join(this.root, `.write-test-${process.pid}`);
      await fs.promises.writeFile(probe, 'ok');
      await fs.promises.rm(probe);
      return null;
    } catch (e) {
      return `The uploads folder ${this.root} is not writable by the app (uid ${process.getuid?.() ?? '?'}): ${(e as Error).message}`;
    }
  }
}

/** Minimal S3 client (Signature V4, path-style) for PUT/GET/DELETE of single objects. */
export class S3Blobs implements BlobStore {
  readonly driver = 's3';
  constructor(private readonly s3: Config['s3']) {}

  private url(key: string): URL {
    const base = new URL(this.s3.endpoint);
    const k = key.split('/').map(encodeURIComponent).join('/');
    if (this.s3.forcePathStyle) return new URL(`${base.origin}/${this.s3.bucket}/${k}`);
    return new URL(`${base.protocol}//${this.s3.bucket}.${base.host}/${k}`);
  }

  private sign(method: string, url: URL, body: Buffer | null): Record<string, string> {
    const now = new Date();
    const amzDate = now.toISOString().replace(/[:-]|\.\d{3}/g, '');
    const day = amzDate.slice(0, 8);
    const hash = crypto
      .createHash('sha256')
      .update(body ?? '')
      .digest('hex');
    const headers: Record<string, string> = { host: url.host, 'x-amz-content-sha256': hash, 'x-amz-date': amzDate };
    const signed = Object.keys(headers).sort();
    const canonical = [method, url.pathname, url.searchParams.toString(), ...signed.map((h) => `${h}:${headers[h]}`), '', signed.join(';'), hash].join('\n');
    const scope = `${day}/${this.s3.region}/s3/aws4_request`;
    const toSign = ['AWS4-HMAC-SHA256', amzDate, scope, crypto.createHash('sha256').update(canonical).digest('hex')].join('\n');
    const h = (k: Buffer | string, d: string) => crypto.createHmac('sha256', k).update(d).digest();
    const key = h(h(h(h(`AWS4${this.s3.secretKey}`, day), this.s3.region), 's3'), 'aws4_request');
    const sig = crypto.createHmac('sha256', key).update(toSign).digest('hex');
    return {
      ...headers,
      authorization: `AWS4-HMAC-SHA256 Credential=${this.s3.accessKey}/${scope}, SignedHeaders=${signed.join(';')}, Signature=${sig}`,
    };
  }

  private async req(method: string, key: string, body: Buffer | null = null) {
    const url = this.url(key);
    const res = await fetch(url, { method, headers: this.sign(method, url, body), body: body ? new Uint8Array(body) : undefined });
    return res;
  }
  async put(key: string, data: Buffer) {
    const r = await this.req('PUT', key, data);
    if (!r.ok) throw new Error(`S3 upload failed: ${r.status}`);
  }
  async get(key: string) {
    const r = await this.req('GET', key);
    if (r.status === 404) return null;
    if (!r.ok || !r.body) throw new Error(`S3 download failed: ${r.status}`);
    return Readable.fromWeb(r.body as never);
  }
  async delete(key: string) {
    const r = await this.req('DELETE', key);
    if (!r.ok && r.status !== 404) throw new Error(`S3 delete failed: ${r.status}`);
  }
  async space() {
    return null;
  }
  async check() {
    try {
      await this.put('_health/probe', Buffer.from('ok'));
      await this.delete('_health/probe');
      return null;
    } catch (e) {
      return `S3 storage is not usable: ${(e as Error).message}`;
    }
  }
}

/** Recognises the picture formats the boards accept from their first bytes. */
export function sniffImage(b: Buffer): string | null {
  if (b.length < 12) return null;
  if (b[0] === 0x89 && b.toString('latin1', 1, 4) === 'PNG') return 'image/png';
  if (b[0] === 0xff && b[1] === 0xd8 && b[2] === 0xff) return 'image/jpeg';
  if (b.toString('latin1', 0, 6) === 'GIF87a' || b.toString('latin1', 0, 6) === 'GIF89a') return 'image/gif';
  if (b.toString('latin1', 0, 4) === 'RIFF' && b.toString('latin1', 8, 12) === 'WEBP') return 'image/webp';
  if (b[0] === 0x42 && b[1] === 0x4d) return 'image/bmp';
  if (b.readUInt32BE(0) === 0x00000100) return 'image/x-icon';
  return null;
}

export async function dirSize(dir: string): Promise<number> {
  let total = 0;
  const walk = async (d: string) => {
    let entries: fs.Dirent[];
    try {
      entries = await fs.promises.readdir(d, { withFileTypes: true });
    } catch {
      return;
    }
    for (const e of entries) {
      const p = path.join(d, e.name);
      if (e.isDirectory()) await walk(p);
      else if (e.isFile()) total += (await fs.promises.stat(p)).size;
    }
  };
  await walk(dir);
  return total;
}
